using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class TaiSanDAL
{
 public async Task<List<ThietBi>> LayThietBiAsync(){const string q="SELECT t.MaTB,t.TenTB,l.TenLoaiTB,p.TenPhong,t.NgayMua,t.TinhTrang FROM dbo.ThietBi t JOIN dbo.LoaiThietBi l ON l.MaLoaiTB=t.MaLoaiTB LEFT JOIN dbo.PhongTap p ON p.MaPhong=t.MaPhong ORDER BY t.MaTB DESC;";var k=new List<ThietBi>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new ThietBi{MaTB=r.GetInt32(0),TenTB=r.GetString(1),LoaiThietBi=r.GetString(2),Phong=r.IsDBNull(3)?null:r.GetString(3),NgayMua=r.IsDBNull(4)?null:r.GetDateTime(4),TinhTrang=r.GetString(5)});return k;}
 public async Task<List<PhongTapModel>> LayPhongAsync(){const string q="SELECT MaPhong,TenPhong,LoaiPhong,SucChua,DienTich,Tang,TrangThai FROM dbo.PhongTap ORDER BY Tang,TenPhong;";var k=new List<PhongTapModel>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new PhongTapModel{MaPhong=r.GetInt32(0),TenPhong=r.GetString(1),LoaiPhong=r.GetString(2),SucChua=r.GetInt32(3),DienTich=r.IsDBNull(4)?null:r.GetDecimal(4),Tang=r.GetInt32(5),TrangThai=r.GetString(6)});return k;}
 public async Task<List<BaoTri>> LayBaoTriAsync(){const string q="SELECT b.MaBaoTri,t.TenTB,n.HoTen,b.NgayBaoTri,b.NoiDung,b.ChiPhi,b.TrangThai FROM dbo.BaoTriThietBi b JOIN dbo.ThietBi t ON t.MaTB=b.MaTB JOIN dbo.NhanVien n ON n.MaNV=b.MaNV ORDER BY b.MaBaoTri DESC;";var k=new List<BaoTri>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new BaoTri{MaBaoTri=r.GetInt32(0),ThietBi=r.GetString(1),NhanVien=r.GetString(2),NgayBaoTri=r.GetDateTime(3),NoiDung=r.GetString(4),ChiPhi=r.GetDecimal(5),TrangThai=r.GetString(6)});return k;}
 public async Task TaoBaoTriAsync(int tb,int nv,string nd,decimal cp){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_BaoTriThietBi",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTB",tb);m.Parameters.AddWithValue("@MaNV",nv);m.Parameters.AddWithValue("@NoiDung",nd);m.Parameters.AddWithValue("@ChiPhi",cp);m.Parameters.AddWithValue("@NgayDuKien",DBNull.Value);var o=m.Parameters.Add("@MaBaoTri",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();}
}
